-- UNA-Migration-Min-System-Version: 15.0.0-RC4
-- The site's splash is in the guests' page shell (2026111880), and the default splash code lost its own header and
-- footer. That migration looked for the previous default exactly, and missed a site where Studio > Designer > Splash
-- was saved once: the browser shows the footer's &copy; in the code field as the copyright sign, and the save stores
-- the sign. Such a site showed two headers and two footers. This one takes the previous default with either form of
-- the sign and either line endings; code an operator changed is left as it is. Running it again changes nothing.
UPDATE `sys_options` SET `value` = '<style>\r\n    /* Guest splash, laid out like the built-in splash of the apps. The colours follow the light and dark scheme.\r\n       The site and the apps show it between their own header and footer (the web app in .neo-splash), so it has\r\n       none of its own. The apps leave out what has data-site-only. */\r\n    .bx-landing {\r\n        --bx-landing-muted: #e4e4e7;\r\n        --bx-landing-accent: #dbeafe;\r\n        --bx-landing-accent-fg: #1d4ed8;\r\n        --bx-landing-primary: #2563eb;\r\n        --bx-landing-title: #0a0a0c;\r\n        --bx-landing-text: #52525b;\r\n        --bx-landing-border: #e4e4e7;\r\n        display: flex;\r\n        flex-direction: column;\r\n        min-height: calc(100vh - 4rem); /* the first screen, under the site header */\r\n        min-height: calc(100dvh - 4rem);\r\n    }\r\n    .dark .bx-landing,\r\n    [data-theme="dark"] .bx-landing {\r\n        --bx-landing-muted: #3f3f46;\r\n        --bx-landing-accent: #172554;\r\n        --bx-landing-accent-fg: #60a5fa;\r\n        --bx-landing-title: #fafafc;\r\n        --bx-landing-text: #a1a1aa;\r\n        --bx-landing-border: #3f3f46;\r\n    }\r\n    @media (prefers-color-scheme: dark) {\r\n        :root:not([data-theme="light"]) .neo-splash .bx-landing {\r\n            --bx-landing-muted: #3f3f46;\r\n            --bx-landing-accent: #172554;\r\n            --bx-landing-accent-fg: #60a5fa;\r\n            --bx-landing-title: #fafafc;\r\n            --bx-landing-text: #a1a1aa;\r\n            --bx-landing-border: #3f3f46;\r\n        }\r\n    }\r\n    .neo-splash .bx-landing {\r\n        flex: 1 1 auto;\r\n        min-height: 0;\r\n    }\r\n    .bx-landing-main {\r\n        display: flex;\r\n        flex: 1 1 auto;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        justify-content: center;\r\n        gap: 1.5rem;\r\n        box-sizing: border-box;\r\n        width: 100%;\r\n        max-width: 88rem;\r\n        margin: 0 auto;\r\n        padding: 1rem;\r\n    }\r\n    .bx-landing-intro {\r\n        display: flex;\r\n        flex: 1 1 auto;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        gap: 1.5rem;\r\n        width: 100%;\r\n        text-align: center;\r\n    }\r\n    .bx-landing-art {\r\n        display: block;\r\n        width: 12rem;\r\n        height: 12rem;\r\n    }\r\n    .bx-landing-title {\r\n        margin: 0;\r\n        color: var(--bx-landing-title);\r\n        font-size: 2.25rem;\r\n        font-weight: 700;\r\n        line-height: 1.25;\r\n        letter-spacing: -0.025em;\r\n        text-wrap: balance;\r\n    }\r\n    .bx-landing-text {\r\n        max-width: 48rem;\r\n        margin: 0;\r\n        color: var(--bx-landing-text);\r\n        font-size: 1rem;\r\n        line-height: 1.5rem;\r\n        text-wrap: pretty;\r\n    }\r\n    .bx-landing-auth {\r\n        flex: none;\r\n        width: 100%;\r\n        max-width: 28rem;\r\n    }\r\n    @media (min-width: 640px) {\r\n        .bx-landing-main { padding: 1.5rem; }\r\n        .bx-landing-text { font-size: 1.125rem; line-height: 1.75rem; }\r\n    }\r\n    @media (min-width: 1024px) {\r\n        .bx-landing-main {\r\n            flex-direction: row;\r\n            gap: 3rem;\r\n            padding: 3rem;\r\n        }\r\n        .bx-landing-intro {\r\n            align-items: flex-start;\r\n            text-align: start;\r\n        }\r\n    }\r\n    @media (min-width: 1280px) {\r\n        .bx-landing-title { font-size: 3rem; }\r\n    }\r\n</style>\r\n<div class="bx-landing bx-def-color-bg-page">\r\n    <div class="bx-landing-main">\r\n        <div class="bx-landing-intro text-center">\r\n            __illustration__\r\n            <h1 class="bx-landing-title"><bx_text:_sys_txt_splash_title /></h1>\r\n            <p class="bx-landing-text"><bx_text:_sys_txt_splash_slogan /></p>\r\n        </div>\r\n        <div class="bx-landing-auth">__login_form_in_box__</div>\r\n    </div>\r\n</div>'
WHERE `name` = 'sys_site_splash_code' AND REPLACE(REPLACE(`value`, '\r', ''), _utf8mb4 0xC2A9, '&copy;') = REPLACE('<style>\r\n    /* Guest splash, laid out like the built-in splash of the apps. The colours follow the light and dark scheme.\r\n       The apps leave out what has data-site-only (they draw their own header and footer); the web app puts the\r\n       code in .neo-splash, between its header and footer. */\r\n    .bx-landing {\r\n        --bx-landing-muted: #e4e4e7;\r\n        --bx-landing-accent: #dbeafe;\r\n        --bx-landing-accent-fg: #1d4ed8;\r\n        --bx-landing-primary: #2563eb;\r\n        --bx-landing-title: #0a0a0c;\r\n        --bx-landing-text: #52525b;\r\n        --bx-landing-border: #e4e4e7;\r\n        display: flex;\r\n        flex-direction: column;\r\n        min-height: 100vh;\r\n    }\r\n    .dark .bx-landing,\r\n    [data-theme="dark"] .bx-landing {\r\n        --bx-landing-muted: #3f3f46;\r\n        --bx-landing-accent: #172554;\r\n        --bx-landing-accent-fg: #60a5fa;\r\n        --bx-landing-title: #fafafc;\r\n        --bx-landing-text: #a1a1aa;\r\n        --bx-landing-border: #3f3f46;\r\n    }\r\n    @media (prefers-color-scheme: dark) {\r\n        :root:not([data-theme="light"]) .neo-splash .bx-landing {\r\n            --bx-landing-muted: #3f3f46;\r\n            --bx-landing-accent: #172554;\r\n            --bx-landing-accent-fg: #60a5fa;\r\n            --bx-landing-title: #fafafc;\r\n            --bx-landing-text: #a1a1aa;\r\n            --bx-landing-border: #3f3f46;\r\n        }\r\n    }\r\n    .neo-splash .bx-landing {\r\n        flex: 1 1 auto;\r\n        min-height: 0;\r\n    }\r\n    .bx-landing-header,\r\n    .bx-landing-footer {\r\n        display: flex;\r\n        flex-wrap: wrap;\r\n        align-items: center;\r\n        justify-content: space-between;\r\n        gap: 0.75rem;\r\n        padding: 0.75rem 1rem;\r\n    }\r\n    .bx-landing-header {\r\n        min-height: 4rem;\r\n        box-sizing: border-box;\r\n    }\r\n    .bx-landing-footer {\r\n        border-top: 1px solid var(--bx-landing-border);\r\n        color: var(--bx-landing-text);\r\n        font-size: 0.875rem;\r\n    }\r\n    .bx-landing-main {\r\n        display: flex;\r\n        flex: 1 1 auto;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        justify-content: center;\r\n        gap: 1.5rem;\r\n        box-sizing: border-box;\r\n        width: 100%;\r\n        max-width: 88rem;\r\n        margin: 0 auto;\r\n        padding: 1rem;\r\n    }\r\n    .bx-landing-intro {\r\n        display: flex;\r\n        flex: 1 1 auto;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        gap: 1.5rem;\r\n        width: 100%;\r\n        text-align: center;\r\n    }\r\n    .bx-landing-art {\r\n        display: block;\r\n        width: 12rem;\r\n        height: 12rem;\r\n    }\r\n    .bx-landing-title {\r\n        margin: 0;\r\n        color: var(--bx-landing-title);\r\n        font-size: 2.25rem;\r\n        font-weight: 700;\r\n        line-height: 1.25;\r\n        letter-spacing: -0.025em;\r\n        text-wrap: balance;\r\n    }\r\n    .bx-landing-text {\r\n        max-width: 48rem;\r\n        margin: 0;\r\n        color: var(--bx-landing-text);\r\n        font-size: 1rem;\r\n        line-height: 1.5rem;\r\n        text-wrap: pretty;\r\n    }\r\n    .bx-landing-auth {\r\n        flex: none;\r\n        width: 100%;\r\n        max-width: 28rem;\r\n    }\r\n    .bx-landing-links {\r\n        display: flex;\r\n        flex-wrap: wrap;\r\n        gap: 1rem;\r\n    }\r\n    @media (min-width: 640px) {\r\n        .bx-landing-main { padding: 1.5rem; }\r\n        .bx-landing-text { font-size: 1.125rem; line-height: 1.75rem; }\r\n    }\r\n    @media (min-width: 1024px) {\r\n        .bx-landing-main {\r\n            flex-direction: row;\r\n            gap: 3rem;\r\n            padding: 3rem;\r\n        }\r\n        .bx-landing-intro {\r\n            align-items: flex-start;\r\n            text-align: start;\r\n        }\r\n    }\r\n    @media (min-width: 1280px) {\r\n        .bx-landing-title { font-size: 3rem; }\r\n    }\r\n</style>\r\n<div class="bx-landing bx-def-color-bg-page">\r\n    <header class="bx-landing-header" data-site-only>\r\n        __logo__\r\n        <a class="bx-btn bx-btn-primary" href="__join_link__"><bx_text:_sys_txt_splash_join /></a>\r\n    </header>\r\n    <main class="bx-landing-main">\r\n        <div class="bx-landing-intro text-center">\r\n            __illustration__\r\n            <h1 class="bx-landing-title"><bx_text:_sys_txt_splash_title /></h1>\r\n            <p class="bx-landing-text"><bx_text:_sys_txt_splash_slogan /></p>\r\n        </div>\r\n        <div class="bx-landing-auth">__login_form_in_box__</div>\r\n    </main>\r\n    <footer class="bx-landing-footer" data-site-only>\r\n        <nav class="bx-landing-links">\r\n            <a href="<bx_url_root />page.php?i=terms"><bx_text:_sys_menu_item_title_terms /></a>\r\n            <a href="<bx_url_root />page.php?i=privacy"><bx_text:_sys_menu_item_title_privacy /></a>\r\n        </nav>\r\n        <span>&copy; {site_title}</span>\r\n    </footer>\r\n</div>', '\r', '');
